css:
/* generated child CSS: 02-footer/footer.default/block.css */
/* lab-ui block · footer.default
   Depends: 00-tokens/tokens.css (--color-black-bg, --color-white,
   --color-gray-blue, --font-family, --container-*).
   Dark surface regardless of host page theme. */

.footer {
  background: var(--color-black-bg, #17171B);
  color: var(--color-gray-light, #D9D9D9);
  padding: 64px 0 32px;
  font-family: var(--font-family);
  border-top-left-radius: 2.5rem;
  border-top-right-radius: 2.5rem;
}

.footer .container,
.footer .footer-container {
  max-width: calc(var(--container-width) + var(--container-padding-x) * 2);
  margin-inline: auto;
  padding-inline: var(--container-padding-x);
}

.footer-top {
  display: grid;
  grid-template-columns: 1.4fr 1fr 1fr;
  gap: 48px;
  align-items: start;
  padding-bottom: 48px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
}

.footer-brand-head {
  margin-bottom: 16px;
}
.footer-logo {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  color: var(--color-white);
  text-decoration: none;
  font-size: 1.5rem;
  font-weight: 600;
  letter-spacing: -0.02em;
}
.footer-tagline {
  font-size: 0.9375rem;
  color: var(--color-gray-light);
  max-width: 22rem;
  margin: 0 0 24px;
  line-height: 1.5;
}
.footer-address {
  font-style: normal;
  font-size: 0.8125rem;
  color: var(--color-gray-blue);
  line-height: 1.65;
}
.footer-address p { margin: 0; }
.footer-address strong { color: var(--color-white); font-weight: 600; }

.footer-nav {
  display: grid;
  gap: 14px;
  font-size: 0.9375rem;
}
.footer-nav-link {
  color: var(--color-gray-light);
  text-decoration: none;
  transition: color var(--transition-duration) ease;
}
.footer-nav-link:hover { color: var(--color-white); }

.footer-contacts { display: grid; gap: 32px; }
.footer-socials {
  display: inline-flex;
  gap: 8px;
}
.footer-social-link {
  display: inline-grid;
  place-items: center;
  width: 32px;
  height: 32px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.06);
  color: var(--color-white);
  transition: background var(--transition-duration) ease;
}
.footer-social-link:hover { background: rgba(255, 255, 255, 0.12); }

.footer-emails {
  display: grid;
  gap: 16px;
}
.footer-email-label {
  font-family: var(--font-mono);
  font-size: 0.6875rem;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--color-gray-blue);
  margin: 0 0 4px;
}
.footer-email-link {
  font-size: 0.9375rem;
  color: var(--color-white);
  text-decoration: none;
  border-bottom: 1px solid rgba(255, 255, 255, 0.16);
  padding-bottom: 1px;
}
.footer-email-link:hover { border-bottom-color: var(--color-white); }

.footer-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding-top: 24px;
  font-size: 0.8125rem;
}
.footer-copy { color: var(--color-gray-blue); margin: 0; }
.footer-legal-mobile { display: inline-flex; gap: 16px; }
.footer-legal-link {
  color: var(--color-gray-blue);
  text-decoration: none;
  transition: color var(--transition-duration) ease;
}
.footer-legal-link:hover { color: var(--color-white); }

@media (max-width: 900px) {
  .footer-top { grid-template-columns: 1fr 1fr; gap: 32px; }
  .footer-contacts { grid-column: span 2; }
}
@media (max-width: 600px) {
  .footer-top { grid-template-columns: 1fr; }
  .footer-contacts { grid-column: span 1; }
  .footer-bottom { flex-direction: column; align-items: flex-start; gap: 12px; }
}
